"""Sponsorship package model — generated by FR-005 agent."""

import uuid

from sqlalchemy import ForeignKey, Integer
from sqlalchemy.dialects.postgresql import UUID, JSONB
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base, TimestampMixin, UUIDPrimaryKeyMixin


class SponsorshipPackage(Base, UUIDPrimaryKeyMixin, TimestampMixin):
    """AI-generated sponsorship tiers and outreach materials."""

    __tablename__ = "sponsorship_packages"

    event_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("event_records.id", ondelete="CASCADE"),
        nullable=False, index=True, unique=True,
    )
    version: Mapped[int] = mapped_column(Integer, default=1, nullable=False)
    tiers: Mapped[list] = mapped_column(JSONB, nullable=False)
    # tiers = [
    #   {"name": "Gold", "amount": 200000, "benefits": ["Logo on banner", ...]},
    #   {"name": "Silver", "amount": 100000, "benefits": [...]},
    #   {"name": "Bronze", "amount": 50000, "benefits": [...]}
    # ]
    audience_summary: Mapped[str | None] = mapped_column(JSONB, nullable=True)
    email_drafts: Mapped[list | None] = mapped_column(JSONB, nullable=True)
    # email_drafts = [
    #   {"industry": "tech", "subject_a": "...", "subject_b": "...", "body": "..."},
    #   ...
    # ]
